window.products.push({"id":937732,"name":"Wild Safari - African Jungle Adventure Birthday Party or Baby Shower Favor Boxes - Set of 12","category":"homeandappliances","retail price":19.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81t2Niluf-L._AC_SL1500_.jpg","description":"Include the display of sweet treats into your party decor by using our themed Wild Safari - African Jungle Adventure Birthday Party or Baby Shower Favor Boxes! These gift bags are sold in sets of 12, are the perfect size for your favorite candy, prize or treat! Display several in a grouping on a candy buffet table allowing guests to sample several treats, or send each person home with their own individual treat box! Custom printed with our original artwork, these bags are created with a heavy duty satin paper that gives the finished product a photo like shine! The perfect complement to any celebration, you’ll love our themed party gift bags!","images":["https://m.media-amazon.com/images/I/81t2Niluf-L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Big Dot of Happiness","source_asin":"B07BKSXXLK","category_path":"Home & Kitchen"},"sku":"BM-937732","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07BKSXXLK","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07BKSXXLK","price_pending":true,"merchant_ready":false});
